/**
 * Road traffic: the dispatched fleet that drives the city's road network.
 *
 * `VehiclesSystem` owns every vehicle the city runs and turns the commute
 * intent published by `src/sim/citizens.ts` into actual traffic on the road
 * graph generated by `src/sim/world.ts`:
 *
 * - **records** — each vehicle is a shared-contract `Vehicle` (kind, plate,
 *   capacity, owner, route, occupancy, fuel, speed, heading, position);
 * - **dispatch** — commute legs become rides (car, taxi, bus, tram, bicycle),
 *   the city's warehouses and shops become freight runs, and a scheduled
 *   service fleet holds the {@link MIN_ACTIVE_VEHICLES} floor around the clock:
 *   {@link DEFAULT_SERVICE_FLEET_SIZE} vehicles from
 *   {@link SERVICE_START_HOUR} to {@link SERVICE_END_HOUR}, and the leaner
 *   {@link DEFAULT_NIGHT_FLEET_SIZE} skeleton overnight, when every
 *   demand-dispatched vehicle has parked and been recycled;
 * - **driving** — vehicles follow real road-graph routes at kind-specific
 *   speeds, brake for the vehicle ahead and yield at intersections;
 * - **service** — commuters board at the entrance of the building they travel
 *   from and alight at the entrance of the building they travel to, with
 *   `Vehicle.occupancy`, `Vehicle.occupantIds` and `Citizen.vehicleId` kept in
 *   sync while they ride;
 * - **recycling** — a finished vehicle parks, refuels and drops into a pool,
 *   where the *same object* (same id, same plate) is dispatched again. Nothing
 *   is discarded, so a multi-day soak keeps a bounded fleet instead of leaking
 *   one vehicle per trip.
 *
 * The module is DOM-free: it imports `./clock`, `./engine`, `./rng`, `./types`,
 * `./world` and the citizen *types* only, and never touches browser globals.
 * The economy is out of scope here - freight demand is derived from the world's
 * own warehouse/factory/shop geometry and used as a dispatch signal.
 */

import { MINUTES_PER_HOUR } from './clock';
import type { CitizensSystem, CommuteIntent, CommuteMode } from './citizens';
import type { EngineContext, SimSystem, SimulationEngine } from './engine';
import { createRng } from './rng';
import type { Rng } from './rng';
import { VEHICLE_KINDS } from './types';
import type {
  Building,
  Citizen,
  CompanySector,
  EntityId,
  RoadNode,
  RoadSegment,
  Vehicle,
  VehicleKind,
  VehicleRoute,
  Vec2,
  WorldMap,
} from './types';
import { buildingCenter, distanceBetweenPoints } from './world';
import type { RoutePath } from './world';

/* ------------------------------------------------------------- constants -- */

/** Engine system name used by the application composition. */
export const VEHICLES_SYSTEM_NAME = 'vehicles';

/**
 * Vehicles the city promises to keep on the road at every hour of the day, and
 * in particular through the commuter peaks in {@link COMMUTE_PEAKS}.
 */
export const MIN_ACTIVE_VEHICLES = 10;

/** Vehicles the scheduled service runs during service hours (peaks included). */
export const DEFAULT_SERVICE_FLEET_SIZE = 12;

/**
 * Vehicles kept running overnight. The city promises at least
 * {@link MIN_ACTIVE_VEHICLES} vehicles at every hour of the day, so the
 * overnight skeleton is exactly that floor: the demand-dispatched cars, buses,
 * trams and bicycles park and recycle, and only the scheduled service runs.
 */
export const DEFAULT_NIGHT_FLEET_SIZE = MIN_ACTIVE_VEHICLES;

/** Hard cap on simultaneously active vehicles, so demand cannot run away. */
export const DEFAULT_MAX_ACTIVE_VEHICLES = 48;

/** Hour-of-day the scheduled service fleet starts running. */
export const SERVICE_START_HOUR = 5;

/** Hour-of-day the scheduled service fleet stops running. */
export const SERVICE_END_HOUR = 23;

/**
 * The world's `speedLimit` values are walking-scale planning figures (0.45-0.6
 * tiles per sim-minute, roughly 14-19 px/min). Road traffic drives at a paced
 * multiple of them, which is what makes a crosstown trip take a plausible slice
 * of the day instead of most of it. Kind ceilings in {@link VEHICLE_KIND_SPECS}
 * still apply on top.
 */
export const ROAD_PACE_MULTIPLIER = 6;

/** A commuter peak: the stretch of day the >=10 vehicle floor has to hold in. */
export interface CommutePeak {
  readonly id: string;
  readonly label: string;
  readonly startHour: number;
  readonly endHour: number;
}

/** Morning and evening commuter peaks, driven by the citizens' shift patterns. */
export const COMMUTE_PEAKS: readonly CommutePeak[] = [
  { id: 'morning', label: 'morning peak', startHour: 5, endHour: 10 },
  { id: 'evening', label: 'evening peak', startHour: 16, endHour: 21 },
];

/** Tiles a vehicle looks ahead for a claim held by another vehicle. */
const NODE_YIELD_DISTANCE_TILES = 2.5;
/** Distance from a node at which a vehicle claims it for this tick. */
const NODE_ZONE_TILES = 2;
/** After this long waiting at an occupied node a vehicle creeps forward. */
const MAX_YIELD_MINUTES = 3;
/** Creep speed as a fraction of free flow, once a vehicle has waited too long. */
const YIELD_CREEP_FACTOR = 0.35;
/** Time a follower wants between itself and the vehicle ahead. */
const FOLLOW_HEADWAY_MINUTES = 1.1;
/** Extra gap a follower keeps on top of the leader's own length. */
const FOLLOW_GAP_TILES = 1.5;
/** Safety valve: how many road segments one tick may cross. */
const MAX_SEGMENTS_PER_TICK = 8;
/** How long a commuter waits for their ride before giving up. */
const MAX_RIDER_WAIT_MINUTES = 60;
/** How long a scheduled transit vehicle stays out on its line. */
const TRANSIT_SERVICE_MINUTES = 150;
/** How long a delivery van stays out on its run. */
const FREIGHT_SERVICE_MINUTES = 120;
/** Shortest freight corridor worth dispatching a van for, in tiles. */
const MIN_FREIGHT_DISTANCE_TILES = 25;
/** Stop dwell a pre-positioned ride waits for a commuter at the kerb. */
const PREPOSITIONED_WAIT_MINUTES = 6;
/** Ring buffer size of the recent event log. */
const EVENT_LOG_LIMIT = 1024;
/** Corridors a coverage slot may pick from, spread over the busiest ones. */
const CORRIDOR_CHOICE_SPREAD = 5;

