/** Vehicle kind that carries a commuter travelling in the given mode. */
export function vehicleKindForCommuteMode(mode: CommuteMode): VehicleKind | null {
  switch (mode) {
    case 'car':
      return 'car';
    case 'bus':
      return 'bus';
    case 'tram':
      return 'tram';
    case 'bicycle':
      return 'bicycle';
    default:
      return null;
  }
}

/** Whether a minute-of-day falls inside one of the commuter peaks. */
export function isCommutePeak(minuteOfDay: number): boolean {
  return peakForMinute(minuteOfDay) !== null;
}

/** The peak a minute-of-day belongs to, or `null` outside every peak. */
export function peakForMinute(minuteOfDay: number): CommutePeak | null {
  const hour = Math.floor(((minuteOfDay % 1440) + 1440) % 1440 / MINUTES_PER_HOUR);
  for (const peak of COMMUTE_PEAKS) {
    if (hour >= peak.startHour && hour < peak.endHour) {
      return peak;
    }
  }
  return null;
}

/** Speed a kind may use on a segment with the given speed limit. */
export function pacedSpeedLimit(segmentSpeedLimit: number, kind: VehicleKind): number {
  const spec = VEHICLE_KIND_SPECS[kind];
  return Math.min(spec.maxSpeed, segmentSpeedLimit * ROAD_PACE_MULTIPLIER);
}

/* ---------------------------------------------------------------- inputs -- */

/**
 * The slice of the world the traffic system needs: the shared `WorldMap`
 * contract plus the routing lookups `CityWorld` already provides.
 */
export interface VehicleWorld extends WorldMap {
  readonly buildings: Building[];
  roadNodeById(nodeId: EntityId): RoadNode | null;
  routeBetweenNodes(fromNodeId: EntityId, toNodeId: EntityId): RoutePath | null;
  nearestRoadNode(point: Vec2): RoadNode;
}

/** A commute corridor the fleet may work: one building to another. */
export interface CommuteCorridor {
  readonly id: string;
  readonly kind: VehicleKind;
  readonly mode: CommuteMode;
  readonly fromBuildingId: EntityId;
  readonly toBuildingId: EntityId;
  readonly fromNodeId: EntityId;
  readonly toNodeId: EntityId;
  readonly distanceTiles: number;
  /** Commute legs in the roster that use this corridor. */
  readonly legs: number;
}

/** A freight corridor: goods from a warehouse/factory to a shop or store. */
export interface FreightRun {
  readonly id: string;
  readonly vehicleKind: VehicleKind;
  readonly sourceBuildingId: EntityId;
  readonly destinationBuildingId: EntityId;
  readonly sourceNodeId: EntityId;
  readonly destinationNodeId: EntityId;
  readonly distanceTiles: number;
}

/** One stop of a vehicle's plan. */
export interface VehicleStop {
  readonly nodeId: EntityId;
  readonly buildingId: EntityId | null;
  readonly action: 'board' | 'alight' | 'service' | 'park';
  readonly dwellMinutes: number;
}

/* --------------------------------------------------------------- options -- */

/** Constructor options for {@link VehiclesSystem}. */
export interface VehiclesOptions {
  /** The generated city the fleet drives in. */
  readonly world: VehicleWorld;
  /** Citizen roster that supplies commute intent; optional for fleet-only use. */
  readonly citizens?: CitizensSystem | null;
  /** Fleet seed; defaults to the world seed (or the world id). */
  readonly seed?: number | string;
  /** Engine system name; defaults to {@link VEHICLES_SYSTEM_NAME}. */
  readonly systemName?: string;
  /** Vehicles kept on the road during service hours. Defaults to 12. */
  readonly serviceFleetSize?: number;
  /** Vehicles kept on the road at night. Defaults to 4. */
  readonly nightFleetSize?: number;
  /** Hard cap on simultaneously active vehicles. Defaults to 48. */
  readonly maxActiveVehicles?: number;
}

